use freedom_consensus::{validate_genesis,ConsensusConfig};
use freedom_crypto::verify;
use freedom_primitives::{CHAIN_ID,Hash};
use freedom_state::{ChainState,StateError};
use freedom_types::{Genesis,Receipt,Transaction};

pub fn initialize(genesis:&Genesis)->Result<ChainState,String>{if genesis.chain_id!=CHAIN_ID{return Err("invalid chain id".into())}let state=ChainState::genesis(genesis);validate_genesis(&state,&ConsensusConfig::default())?;state.assert_invariants();Ok(state)}
pub fn execute_transaction(state:&mut ChainState,tx:&Transaction)->Result<Receipt,String>{if tx.chain_id!=CHAIN_ID{return Err("invalid chain id".into())}let a=state.accounts.get(&tx.sender).ok_or_else(||"sender account not found".to_string())?;if tx.signature.len()!=64{return Err("invalid signature length".into())}let mut s=[0u8;64];s.copy_from_slice(&tx.signature);if !verify(&a.public_key,&tx.signing_bytes(),&s){return Err("invalid transaction signature".into())}let h:Hash=tx.hash();state.execute_transaction(tx).map_err(format_state_error)?;state.assert_invariants();Ok(Receipt{tx_hash:h,success:true,gas_used:1})}
fn format_state_error(e:StateError)->String{match e{StateError::AccountNotFound=>"sender account not found".into(),StateError::InvalidNonce{expected,actual}=>format!("invalid nonce: expected {expected}, got {actual}"),StateError::InsufficientBalance=>"insufficient balance".into(),StateError::InvalidTransferPayload=>"invalid transfer payload".into(),StateError::InvalidRecipient=>"invalid recipient".into(),StateError::ArithmeticOverflow=>"arithmetic overflow".into(),StateError::UnsupportedTransaction=>"unsupported transaction".into(),StateError::InvalidNodePayload=>"invalid node payload".into(),StateError::InvalidNode=>"invalid node".into(),StateError::DuplicateNode=>"duplicate node".into(),StateError::InvalidContributionPayload=>"invalid contribution payload".into(),StateError::InvalidContribution=>"invalid contribution".into(),StateError::DuplicateContribution=>"duplicate contribution".into(),StateError::InvalidWorkUnits=>"work units must be greater than zero".into(),StateError::InvalidQualityScore=>"quality score must be 0..=10000".into(),StateError::InvalidVerification=>"invalid verification".into(),StateError::AlreadyVerified=>"contribution already verified".into()}}
#[cfg(test)]mod tests{use super::*;use freedom_crypto::{generate_keypair,sign};use freedom_primitives::{address_from_public_key,hash_bytes};use freedom_state::{Account,ContributionStatus};use freedom_types::{RegisterNodePayload,SubmitContributionPayload,TxKind};
fn tx(k:&ed25519_dalek::SigningKey,s:[u8;32],n:u64,kind:TxKind,p:Vec<u8>)->Transaction{let mut t=Transaction{chain_id:CHAIN_ID,sender:s,nonce:n,kind,payload:p,fee:0,signature:vec![]};t.signature=sign(k,&t.signing_bytes()).to_vec();t}
#[test]fn contribution_flow(){let ok=generate_keypair();let opk=ok.verifying_key().to_bytes();let owner=address_from_public_key(&opk);let vk=generate_keypair();let vpk=vk.verifying_key().to_bytes();let vid=hash_bytes(&vpk);let mut st=ChainState::genesis(&Genesis{chain_id:CHAIN_ID,initial_supply:0,validators:vec![freedom_types::Validator{validator_id:vid,owner,consensus_key:vpk,stake:0,blocks_proposed:0,blocks_finalized:0,missed_votes:0}]});st.insert_account(Account::new(opk,0));let nid=hash_bytes(b"node-1");execute_transaction(&mut st,&tx(&ok,owner,0,TxKind::RegisterNode,RegisterNodePayload{node_id:nid,capabilities:7}.encode())).unwrap();let cid=hash_bytes(b"c1");let tid=hash_bytes(b"t1");execute_transaction(&mut st,&tx(&ok,owner,1,TxKind::SubmitContribution,SubmitContributionPayload{contribution_id:cid,node_id:nid,task_id:tid,work_units:42,quality_score:9000,result_hash:hash_bytes(b"r")}.encode())).unwrap();assert_eq!(st.contributions.get(&cid).unwrap().status,ContributionStatus::Submitted);st.verify_contribution(cid,vec![vid],9500).unwrap();let c=st.contributions.get(&cid).unwrap();assert_eq!(c.status,ContributionStatus::Verified);assert_eq!(c.verification_score,9500);assert_eq!(st.nodes.get(&nid).unwrap().total_wu,42);}}
